  if (pointer === '') return [];
  if (pointer[0] !== '/') throw new SyntaxError('invalid pointer');
  return pointer.slice(1).split('/').map((token) => {
    if (BAD_ESCAPE_RE.test(token)) throw new SyntaxError('invalid pointer');
