  ["isdir", ["D"], null],
  ["docdir", ["-", "D"], "[]"],
  ["add1", ["-", "D/package.json"], "[{\"op\":\"add\",\"path\":\"/1\",\"value\":5},{\"op\":\"replace\",\"path\":\"\",\"value\":{\"b\":0,\"1\":-0}}]"],
  ["bom", ["-", "D/package.json"], Buffer.from([0xef,0xbb,0xbf,0x5b,0x5d])],
  ["bom2", ["-", "D/package.json"], Buffer.from([0xef,0xbb,0xbf,0xef,0xbb,0xbf,0x5b,0x5d])],
  ["badutf", ["-", "x"], Buffer.from([0x5b,0xff,0x5d])],
  ["surrogate", ["-", "x"], Buffer.from([0x5b,0xed,0xa0,0x80,0x5d])],
  ["empty", ["-", "x"], ""],
  ["badop", ["-", "D/package.json"], "[{\"op\":\"x\"}]"],
  ["notarr", ["-", "D/package.json"], "{}"],
  ["patchfirst", ["-", "nope.json"], "nope"],
  ["deep", ["-", "x"], "[".repeat(1001) + "]".repeat(1001)],
  ["deepok", ["-", "D/package.json"], "[{\"op\":\"test\",\"path\":\"/zz\",\"value\":" + "[".repeat(999) + "]".repeat(999) + "}]"],
  ["big", ["-", "x"], " ".repeat(1048577)],
  ["bigok", ["-", "D/package.json"], " ".repeat(1048574) + "[]"],
  ["nul", ["-", "x"], "[]\u0000"],
];
for (const D of ["W","X","Y","Z"]) {
  console.log("=====", D);
